// Fallback : si RPC non disponible, utiliser l'API REST directement
// Ce nœud parse la réponse Supabase
const response = $input.first().json;

// Supabase REST retourne un tableau directement
const clients = Array.isArray(response) ? response : (response.data || []);

if (clients.length === 0) {
  console.log('Aucun client actif trouvé');
  return [{ json: { _empty: true } }];
}

console.log(`${clients.length} clients actifs à traiter`);
return clients.map(c => ({ json: c }));

// Obtenir un access token Google via le refresh token du client
const client = $input.first().json;

if (!client.google_refresh_token || !client.google_location_id) {
  console.log(`Client ${client.company} : credentials Google manquants, ignoré`);
  return [{ json: { ...client, _skip: true, skip_reason: 'no_google_credentials' } }];
}

return [{ json: { ...client, _skip: false } }];

// Filtrer les avis sans réponse et préparer le traitement
const client     = $('Vérifier credentials Google').first().json;
const response   = $input.first().json;
const reviews    = response.reviews || [];

// Ne garder que les avis sans réponse
const sansReponse = reviews.filter(r => !r.reviewReply);

console.log(`Client ${client.company} : ${reviews.length} avis total, ${sansReponse.length} sans réponse`);

if (sansReponse.length === 0) {
  return [{ json: { ...client, _no_reviews: true } }];
}

// Retourner un item par avis à traiter (max 10 par exécution)
return sansReponse.slice(0, 10).map(review => ({
  json: {
    // Infos client
    client_id:          client.id,
    client_company:     client.company,
    client_sector:      client.sector,
    client_city:        client.city,
    google_account_id:  client.google_account_id,
    google_location_id: client.google_location_id,
    access_token:       $('Obtenir access token Google').first().json.access_token,
    // Infos avis
    review_id:      review.reviewId,
    reviewer_name:  review.reviewer?.displayName || 'Un client',
    reviewer_photo: review.reviewer?.profilePhotoUrl || '',
    rating:         review.starRating === 'FIVE' ? 5 :
                    review.starRating === 'FOUR'  ? 4 :
                    review.starRating === 'THREE' ? 3 :
                    review.starRating === 'TWO'   ? 2 : 1,
    review_text:    review.comment || '',
    review_date:    review.updateTime
  }
}));

// Construire le prompt Claude adapté au secteur et à la note
const avis = $input.first().json;

const secteurContexte = {
  'restauration': 'un restaurant. Sois chaleureux, mentionne le plaisir de recevoir les clients.',
  'beaute':       'un salon de beauté. Sois élégant, remercie pour la confiance accordée.',
  'automobile':   'un garage automobile. Sois professionnel, valorise l\'expertise technique.',
  'auto_ecole':   'une auto-école. Sois encourageant, mentionne la pédagogie et le soutien.',
  'sante':        'un cabinet médical. Sois bienveillant et professionnel, reste sobre.',
  'artisanat':    'un artisan. Valorise le savoir-faire et le soin apporté au travail.',
  'hotellerie':   'un hôtel. Sois chaleureux, invite à revenir, valorise l\'accueil.',
  'services':     'une entreprise de services. Sois professionnel et orienté résultats.'
};

const ctx = secteurContexte[avis.client_sector] || 'un commerce local. Sois chaleureux et professionnel.';

let tonParNote = '';
if (avis.rating >= 4) {
  tonParNote = 'C\'est un avis positif. Exprime une vraie gratitude, personnalise avec le prénom si disponible, invite à revenir.';
} else if (avis.rating === 3) {
  tonParNote = 'C\'est un avis mitigé. Remercie pour le retour, reconnais les points à améliorer sans être défensif, rassure.';
} else {
  tonParNote = 'C\'est un avis négatif. Commence par t\'excuser sincèrement, propose de résoudre le problème en privé, reste calme et constructif. Ne te justifie pas.';
}

const reviewText = avis.review_text
  ? `Texte de l'avis : "${avis.review_text}"`
  : '(L\'avis ne contient pas de texte, seulement une note)';

const prompt = `Tu dois rédiger une réponse à un avis Google pour ${avis.client_company}, qui est ${ctx}

Note donnée : ${avis.rating}/5 étoiles
Auteur : ${avis.reviewer_name}
${reviewText}

Consignes :
${tonParNote}
- Maximum 100 mots
- Commence par le prénom de l'auteur si disponible (ex: "Merci ${avis.reviewer_name} !")
- Ton humain et authentique, jamais robotique
- Ne répète pas la même formule générique ("Merci pour votre avis...")
- Ne mentionne jamais que tu es une IA
- Termine par une invitation à revenir ou un souhait adapté
- Langue : français

Réponds uniquement avec la réponse à publier, sans guillemets ni explication.`;

return [{ json: { ...avis, prompt } }];

