const avis          = $('Préparer prompt Claude').first().json;
const claudeResp    = $input.first().json;
const reponseTexte  = claudeResp.content?.[0]?.text?.trim() || '';

if (!reponseTexte) {
  throw new Error('Claude n\'a pas généré de réponse');
}

return [{ json: { ...avis, reponse_generee: reponseTexte } }];
